diff --git a/cmd/kogen-loop/main.go b/cmd/kogen-loop/main.go
index 9f99fff..8f2fc8d 100644
--- a/cmd/kogen-loop/main.go
+++ b/cmd/kogen-loop/main.go
@@ -182,20 +182,29 @@ func execute(args []string, stdin io.Reader, stderr io.Writer, s *sys.Session, o
 	}
 	fs := flag.NewFlagSet("run", flag.ContinueOnError)
 	fs.SetOutput(stderr)
-	taskPath := fs.String("task", "", "the task: a JSON file, or - for standard input")
+	var taskPath string
+	var taskFlags []string
+	fs.Func("task", "the task: a JSON file, or - for standard input", func(v string) error {
+		taskPath = v
+		taskFlags = append(taskFlags, v)
+		return nil
+	})
 	invalid := func(detail string) (string, int) {
 		return refuse(sys.Fail(api.ErrClassLoop, api.ErrInvalidTask, detail, api.ExitInvalid))
 	}
 	if err := fs.Parse(args); err != nil {
 		return invalid(err.Error())
 	}
+	if len(taskFlags) > 1 {
+		return invalid("the --task option was given more than once; run takes a single --task FILE|-")
+	}
 	if fs.NArg() != 0 {
 		return invalid(fmt.Sprintf("run takes no argument besides --task, got %q", fs.Arg(0)))
 	}
-	if *taskPath == "" {
+	if taskPath == "" {
 		return invalid("run needs --task FILE|- (a task file, or - for standard input)")
 	}
-	task, err := readTask(*taskPath, stdin)
+	task, err := readTask(taskPath, stdin)
 	if err != nil {
 		return refuse(err)
 	}

